# Python — 5-layer encrypt of 0d000721
import base64
plain = "0d000721"
l1 = plain[::-1]
xored = bytes(b ^ 0x5A for b in l1.encode())
l3 = xored.hex()
l4 = base64.b64encode(l3.encode()).decode()
print(l4[::-1])
